package com.samwise0101.rivalry;

import lombok.Value;
import net.runelite.client.hiscore.HiscoreSkillType;

/**
 * One category (skill / boss / activity) as shown in a player's expanded view.
 */
@Value
public class CategoryStat
{
	String name;

	/** RuneLite sprite id for the icon, or -1 if none. */
	int spriteId;

	/** OSRS item id for the icon (used for clue tiers), or -1 if none. */
	int itemId;

	HiscoreSkillType type;

	/**
	 * This player's value relative to the crown holder (or the contested top):
	 * levels for skills, score/KC for bosses and activities. Holder shows their
	 * margin (>= 0); everyone else shows their deficit (<= 0). Null if unranked.
	 */
	Integer diff;

	/**
	 * Same comparison as {@link #diff} but in the crown-ranking metric: XP for
	 * skills (so it differs from the level diff), score/KC for everything else.
	 * Null if unranked.
	 */
	Long crownDiff;

	/** True if this player currently leads the category (holds the crown). */
	boolean holdsCrown;

	/** True if some player strictly leads the category (the crown is not contested). */
	boolean hasHolder;

	/** True for aggregate categories (Total Level, Total Boss KC) — shown in their own row. */
	boolean aggregate;

	/** Display order within a tab (e.g. in-game skill order). Lower comes first. */
	int order;
}

package com.samwise0101.rivalry;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.ToIntFunction;
import java.util.function.ToLongFunction;
import lombok.Value;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;

/**
 * Pure crown computation: given a roster and each player's stats, works out who
 * holds each crown and builds the per-player comparison rows. No I/O, no config,
 * no UI — everything it needs is passed in, so it is fully unit testable.
 */
public class CrownCalculator
{
	static final String TOTAL_LEVEL_ID = "TOTAL_LEVEL";
	static final String TOTAL_BOSS_KC_ID = "TOTAL_BOSS_KC";

	// Skills in the order they appear in the in-game skills tab (3 columns, row by row).
	private static final List<HiscoreSkill> SKILL_ORDER = Arrays.asList(
		HiscoreSkill.ATTACK, HiscoreSkill.HITPOINTS, HiscoreSkill.MINING,
		HiscoreSkill.STRENGTH, HiscoreSkill.AGILITY, HiscoreSkill.SMITHING,
		HiscoreSkill.DEFENCE, HiscoreSkill.HERBLORE, HiscoreSkill.FISHING,
		HiscoreSkill.RANGED, HiscoreSkill.THIEVING, HiscoreSkill.COOKING,
		HiscoreSkill.PRAYER, HiscoreSkill.CRAFTING, HiscoreSkill.FIREMAKING,
		HiscoreSkill.MAGIC, HiscoreSkill.FLETCHING, HiscoreSkill.WOODCUTTING,
		HiscoreSkill.RUNECRAFT, HiscoreSkill.SLAYER, HiscoreSkill.FARMING,
		HiscoreSkill.CONSTRUCTION, HiscoreSkill.HUNTER);

	/**
	 * @param roster ordered player names (display case); the local player is expected first
	 * @param stats  player stats keyed by lowercase name
	 * @param options which category types to include and how to compute gaps
	 */
	public CrownResult calculate(List<String> roster, Map<String, PlayerStats> stats, CrownOptions options)
	{
		Map<String, List<CategoryStat>> statsByPlayer = new HashMap<>();
		Map<String, Integer> crownCount = new HashMap<>();
		for (String p : roster)
		{
			statsByPlayer.put(p, new ArrayList<>());
			crownCount.put(p, 0);
		}

		Map<String, String> holders = new HashMap<>();
		for (CategoryDef def : categories(options))
		{
			processCategory(def, roster, stats, options, statsByPlayer, crownCount, holders);
		}

		List<PlayerStanding> standings = new ArrayList<>();
		for (String p : roster)
		{
			standings.add(new PlayerStanding(p, crownCount.get(p), statsByPlayer.get(p)));
		}
		return new CrownResult(standings, holders);
	}

	/** Human-readable name for a category id (used for notifications etc.). */
	public static String categoryDisplayName(String id)
	{
		if (TOTAL_LEVEL_ID.equals(id))
		{
			return "Total Level";
		}
		if (TOTAL_BOSS_KC_ID.equals(id))
		{
			return "Total Boss KC";
		}
		try
		{
			return HiscoreSkill.valueOf(id).getName();
		}
		catch (IllegalArgumentException e)
		{
			return id;
		}
	}

	private List<CategoryDef> categories(CrownOptions options)
	{
		List<CategoryDef> defs = new ArrayList<>();

		if (options.isTrackSkills())
		{
			defs.add(new CategoryDef(TOTAL_LEVEL_ID, "Total Level", HiscoreSkillType.SKILL,
				net.runelite.api.gameval.SpriteID.SideIcons.STATS, -1, true, -1,
				PlayerStats::overallXp, PlayerStats::totalLevel));
		}
		if (options.isTrackBosses())
		{
			defs.add(new CategoryDef(TOTAL_BOSS_KC_ID, "Total Boss KC", HiscoreSkillType.BOSS,
				-1, -1, true, -1,
				PlayerStats::totalBossKc, PlayerStats::totalBossKc));
		}

		for (HiscoreSkill skill : HiscoreSkill.values())
		{
			HiscoreSkillType type = skill.getType();
			if (type == HiscoreSkillType.OVERALL || !typeEnabled(type, options))
			{
				continue;
			}
			int order = type == HiscoreSkillType.SKILL ? skillOrder(skill) : skill.ordinal();
			defs.add(new CategoryDef(skill.name(), skill.getName(), type,
				skill.getSpriteId(), clueItemId(skill), false, order,
				s -> s.crownValue(skill), s -> s.displayValue(skill)));
		}
		return defs;
	}

	private void processCategory(CategoryDef def, List<String> roster, Map<String, PlayerStats> stats,
		CrownOptions options, Map<String, List<CategoryStat>> statsByPlayer,
		Map<String, Integer> crownCount, Map<String, String> holders)
	{
		// Pass 1: find the leading crown value, count ties, gather per-player values.
		long best = -1;
		int topCount = 0;
		int topDisplay = -1;
		String topPlayer = null;
		Map<String, Integer> displays = new HashMap<>();
		Map<String, Long> crownValues = new HashMap<>();
		for (String name : roster)
		{
			PlayerStats ps = stats.get(name.toLowerCase());
			long crownVal = ps != null ? def.crownValueFn.applyAsLong(ps) : -1;
			int displayVal = ps != null ? def.displayValueFn.applyAsInt(ps) : -1;
			displays.put(name, displayVal);
			crownValues.put(name, crownVal);

			if (crownVal < 0)
			{
				continue;
			}
			if (crownVal > best)
			{
				best = crownVal;
				topCount = 1;
				topPlayer = name;
				topDisplay = displayVal;
			}
			else if (crownVal == best)
			{
				topCount++;
			}
		}

		if (best < 0)
		{
			return; // nobody ranked
		}

		// A crown is only held when a single player strictly leads; a tie is contested.
		String holder = topCount == 1 ? topPlayer : null;
		holders.put(def.id, holder);
		if (holder != null)
		{
			crownCount.merge(holder, 1, Integer::sum);
		}

		// Best display/crown value among players other than the holder (for the holder's margin).
		int runnerUp = 0;
		long runnerUpCrown = 0;
		for (String name : roster)
		{
			if (holder != null && name.equals(holder))
			{
				continue;
			}
			runnerUp = Math.max(runnerUp, displays.get(name));
			runnerUpCrown = Math.max(runnerUpCrown, crownValues.get(name));
		}

		for (String p : roster)
		{
			int displayVal = displays.get(p);
			long crownVal = crownValues.get(p);

			// Skills are always listed; bosses/activities only when this player is ranked.
			if (def.type != HiscoreSkillType.SKILL && displayVal < 0)
			{
				continue;
			}

			boolean holds = holder != null && p.equalsIgnoreCase(holder);
			Integer diff;
			Long crownDiff;
			if (displayVal < 0)
			{
				diff = null;
				crownDiff = null;
			}
			else if (holds)
			{
				diff = topDisplay - runnerUp;
				crownDiff = best - runnerUpCrown;
			}
			else if (options.isGapToNextPlayer())
			{
				long aboveCrown = Long.MAX_VALUE;
				int aboveDisplay = displayVal;
				boolean found = false;
				for (String q : roster)
				{
					long qc = crownValues.get(q);
					if (qc >= 0 && qc > crownVal && qc < aboveCrown)
					{
						aboveCrown = qc;
						aboveDisplay = displays.get(q);
						found = true;
					}
				}
				diff = found ? displayVal - aboveDisplay : 0;
				crownDiff = found ? crownVal - aboveCrown : 0L;
			}
			else
			{
				diff = displayVal - topDisplay;
				crownDiff = crownVal - best;
			}

			statsByPlayer.get(p).add(new CategoryStat(def.displayName, def.spriteId, def.itemId,
				def.type, diff, crownDiff, holds, holder != null, def.aggregate, def.order));
		}
	}

	private static boolean typeEnabled(HiscoreSkillType type, CrownOptions options)
	{
		switch (type)
		{
			case SKILL:
				return options.isTrackSkills();
			case BOSS:
				return options.isTrackBosses();
			case ACTIVITY:
				return options.isTrackActivities();
			default:
				return false;
		}
	}

	private static int skillOrder(HiscoreSkill skill)
	{
		int i = SKILL_ORDER.indexOf(skill);
		return i < 0 ? Integer.MAX_VALUE : i; // unknown/new skills sort last
	}

	/** Maps clue scroll tiers (which lack a sprite) to a representative clue-scroll item id, else -1. */
	private static int clueItemId(HiscoreSkill skill)
	{
		switch (skill)
		{
			case CLUE_SCROLL_BEGINNER:
				return ItemID.TRAIL_CLUE_BEGINNER;
			case CLUE_SCROLL_EASY:
				return ItemID.TRAIL_CLUE_EASY_SIMPLE001;
			case CLUE_SCROLL_MEDIUM:
				return ItemID.TRAIL_CLUE_MEDIUM_SEXTANT001;
			case CLUE_SCROLL_HARD:
				return ItemID.TRAIL_CLUE_HARD_MAP001;
			case CLUE_SCROLL_ELITE:
				return ItemID.TRAIL_ELITE_EMOTE_EXP1;
			case CLUE_SCROLL_MASTER:
				return ItemID.TRAIL_CLUE_MASTER;
			default:
				return -1;
		}
	}

	/** Immutable description of one tracked category. */
	@Value
	private static class CategoryDef
	{
		String id;
		String displayName;
		HiscoreSkillType type;
		int spriteId;
		int itemId;
		boolean aggregate;
		int order;
		ToLongFunction<PlayerStats> crownValueFn;
		ToIntFunction<PlayerStats> displayValueFn;
	}
}

package com.samwise0101.rivalry;

import lombok.Value;

/**
 * The display/category options that influence crown calculation, decoupled from
 * the live {@link RivalryConfig} so {@link CrownCalculator} can be unit tested.
 */
@Value
public class CrownOptions
{
	boolean trackSkills;
	boolean trackBosses;
	boolean trackActivities;

	/** When true, non-holders are compared to the player immediately above them. */
	boolean gapToNextPlayer;
}

package com.samwise0101.rivalry;

import java.util.List;
import java.util.Map;
import lombok.Value;

/**
 * Output of {@link CrownCalculator}: the per-player standings and the current
 * crown holder for each category id (value is null when the crown is contested).
 */
@Value
public class CrownResult
{
	List<PlayerStanding> standings;
	Map<String, String> holders;
}

package com.samwise0101.rivalry;

import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.hiscore.HiscoreSkill;

/**
 * Persists the current crown holder for each category in the plugin's config,
 * so standings survive restarts. A blank/empty holder means "contested / none".
 */
@Singleton
class CrownStore
{
	private static final String KEY_PREFIX = "crown_";

	private final ConfigManager configManager;
	private final Map<String, String> holders = new HashMap<>();

	@Inject
	CrownStore(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	/** Loads stored holders into memory. Call on startup. */
	void load()
	{
		holders.clear();
		for (HiscoreSkill skill : HiscoreSkill.values())
		{
			loadOne(skill.name());
		}
		loadOne(CrownCalculator.TOTAL_LEVEL_ID);
		loadOne(CrownCalculator.TOTAL_BOSS_KC_ID);
	}

	private void loadOne(String id)
	{
		String stored = configManager.getConfiguration(RivalryConfig.GROUP, KEY_PREFIX + id);
		if (stored != null && !stored.isBlank())
		{
			holders.put(id, stored);
		}
	}

	/** The stored holder for a category, or null if none/contested. */
	String getHolder(String id)
	{
		return holders.get(id);
	}

	/** Persists and caches the holder; null is stored as "" (contested). */
	void setHolder(String id, String holder)
	{
		String value = holder != null ? holder : "";
		holders.put(id, value);
		configManager.setConfiguration(RivalryConfig.GROUP, KEY_PREFIX + id, value);
	}
}

package com.samwise0101.rivalry;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.hiscore.HiscoreClient;
import net.runelite.client.hiscore.HiscoreEndpoint;

/**
 * Fetches official hiscore data for a roster. Each player is looked up
 * asynchronously (staggered to be polite); the returned future completes once
 * every lookup has finished, with results collected into a fresh map — so there
 * is no shared mutable state and no fixed-delay guessing.
 */
@Slf4j
@Singleton
class HiscoreService
{
	private static final long STAGGER_MS = 500;

	private final HiscoreClient hiscoreClient;
	private final ScheduledExecutorService executor;

	@Inject
	HiscoreService(HiscoreClient hiscoreClient, ScheduledExecutorService executor)
	{
		this.hiscoreClient = hiscoreClient;
		this.executor = executor;
	}

	CompletableFuture<Map<String, PlayerStats>> fetch(List<String> roster)
	{
		Map<String, PlayerStats> results = new ConcurrentHashMap<>();
		List<CompletableFuture<Void>> lookups = new ArrayList<>();

		for (int i = 0; i < roster.size(); i++)
		{
			final String name = roster.get(i);
			final long delayMs = i * STAGGER_MS;
			final CompletableFuture<Void> done = new CompletableFuture<>();
			lookups.add(done);

			executor.schedule(() ->
				hiscoreClient.lookupAsync(name, HiscoreEndpoint.NORMAL).whenComplete((result, error) ->
				{
					if (error != null)
					{
						log.debug("Hiscore lookup failed for {}: {}", name, error.getMessage());
					}
					else if (result != null)
					{
						results.put(name.toLowerCase(), new PlayerSnapshot(name, result));
					}
					done.complete(null);
				}), delayMs, TimeUnit.MILLISECONDS);
		}

		return CompletableFuture.allOf(lookups.toArray(new CompletableFuture[0]))
			.thenApply(v -> results);
	}
}

package com.samwise0101.rivalry;

import java.awt.Image;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageUtil;

/**
 * Resolves and applies category icons to labels: RuneLite sprites for skills/
 * bosses/activities, item images for clue tiers, and a bundled trophy for
 * aggregates. Loading is asynchronous; the icon is set on the EDT when ready.
 */
@Singleton
class IconLoader
{
	private static final int ICON_SIZE = 18;

	private final SpriteManager spriteManager;
	private final ItemManager itemManager;
	private final ImageIcon trophyIcon;

	@Inject
	IconLoader(SpriteManager spriteManager, ItemManager itemManager)
	{
		this.spriteManager = spriteManager;
		this.itemManager = itemManager;

		BufferedImage trophy = ImageUtil.loadImageResource(getClass(), "/trophy.png");
		this.trophyIcon = new ImageIcon(trophy.getScaledInstance(ICON_SIZE, ICON_SIZE, Image.SCALE_SMOOTH));
	}

	/** Sets the appropriate icon on the label for this category. */
	void apply(JLabel label, CategoryStat stat)
	{
		if (stat.getSpriteId() > 0)
		{
			loadSprite(label, stat.getSpriteId());
		}
		else if (stat.getItemId() > 0)
		{
			loadItem(label, stat.getItemId());
		}
		else if (stat.isAggregate())
		{
			label.setIcon(trophyIcon);
		}
	}

	private void loadSprite(JLabel label, int spriteId)
	{
		spriteManager.getSpriteAsync(spriteId, 0, img ->
		{
			if (img != null)
			{
				setScaled(label, img);
			}
		});
	}

	private void loadItem(JLabel label, int itemId)
	{
		AsyncBufferedImage img = itemManager.getImage(itemId);
		img.onLoaded(() -> setScaled(label, img));
	}

	private static void setScaled(JLabel label, BufferedImage img)
	{
		SwingUtilities.invokeLater(() ->
		{
			label.setIcon(new ImageIcon(img.getScaledInstance(ICON_SIZE, ICON_SIZE, Image.SCALE_SMOOTH)));
			label.revalidate();
			label.repaint();
		});
	}
}

package com.samwise0101.rivalry;

import lombok.Value;
import net.runelite.client.hiscore.HiscoreResult;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;

/**
 * A point-in-time snapshot of a player's hiscore data.
 */
@Value
public class PlayerSnapshot implements PlayerStats
{
	String username;
	HiscoreResult result;

	/**
	 * Value used to rank crowns: total XP for skills, score/KC for bosses and
	 * activities. Returns -1 if unavailable.
	 */
	@Override
	public long crownValue(HiscoreSkill skill)
	{
		if (result == null)
		{
			return -1;
		}
		var s = result.getSkill(skill);
		if (s == null)
		{
			return -1;
		}
		if (skill.getType() == HiscoreSkillType.SKILL)
		{
			return s.getExperience();
		}
		return s.getLevel(); // boss KC / activity score lives in the level field
	}

	/**
	 * Value shown in the UI: level for skills, score/KC for bosses and activities.
	 * Returns -1 if unranked/unavailable.
	 */
	@Override
	public int displayValue(HiscoreSkill skill)
	{
		if (result == null)
		{
			return -1;
		}
		var s = result.getSkill(skill);
		return s == null ? -1 : s.getLevel();
	}

	/** Total XP (Overall experience), or -1 if unavailable. Used to rank the Total Level crown. */
	@Override
	public long overallXp()
	{
		if (result == null)
		{
			return -1;
		}
		var s = result.getSkill(HiscoreSkill.OVERALL);
		return s == null ? -1 : s.getExperience();
	}

	/** Total skill level (Overall level), or -1 if unavailable. */
	@Override
	public int totalLevel()
	{
		if (result == null)
		{
			return -1;
		}
		var s = result.getSkill(HiscoreSkill.OVERALL);
		return s == null ? -1 : s.getLevel();
	}

	/** Sum of all boss kill counts, or -1 if the player is ranked in no bosses. */
	@Override
	public int totalBossKc()
	{
		if (result == null)
		{
			return -1;
		}
		long sum = 0;
		boolean any = false;
		for (HiscoreSkill skill : HiscoreSkill.values())
		{
			if (skill.getType() != HiscoreSkillType.BOSS)
			{
				continue;
			}
			var s = result.getSkill(skill);
			if (s != null && s.getLevel() > 0)
			{
				sum += s.getLevel();
				any = true;
			}
		}
		return any ? (int) sum : -1;
	}
}

package com.samwise0101.rivalry;

import java.util.List;
import lombok.Value;

/**
 * Display data for one player in the standings panel.
 */
@Value
public class PlayerStanding
{
	String name;
	int crownCount;

	/** All categories relevant to this player (skills always; bosses/activities only if ranked). */
	List<CategoryStat> stats;
}

package com.samwise0101.rivalry;

import net.runelite.client.hiscore.HiscoreSkill;

/**
 * The subset of a player's hiscore data the crown logic needs. Abstracting this
 * (rather than passing a live {@link net.runelite.client.hiscore.HiscoreResult})
 * lets {@link CrownCalculator} be unit tested with hand-built data.
 */
public interface PlayerStats
{
	/** Value used to rank crowns: total XP for skills, score/KC otherwise. -1 if unranked. */
	long crownValue(HiscoreSkill skill);

	/** Value shown in the UI: level for skills, score/KC otherwise. -1 if unranked. */
	int displayValue(HiscoreSkill skill);

	/** Total XP (Overall experience), or -1 if unavailable. */
	long overallXp();

	/** Total skill level (Overall level), or -1 if unavailable. */
	int totalLevel();

	/** Sum of all boss kill counts, or -1 if ranked in no bosses. */
	int totalBossKc();
}

package com.samwise0101.rivalry;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(RivalryConfig.GROUP)
public interface RivalryConfig extends Config
{
	String GROUP = "rivalry";
	String CROWN_NOTIFICATION_KEY = "crownNotification";
	String CROWN_NOTIFICATIONS_ENABLED_KEY = "crownNotificationsEnabled";
	String CROWN_GAME_MESSAGE_KEY = "crownGameMessage";
	String CROWN_NOTIFICATION_SOUND_KEY = "crownNotificationSound";
	String CROWN_NOTIFICATION_VOLUME_KEY = "crownNotificationVolume";
	String OLD_NOTIFY_GAME_CHAT_KEY = "notifyGameChat";
	String OLD_NOTIFY_DESKTOP_KEY = "notifyDesktop";

	@ConfigSection(
		name = "Group",
		description = "Populate rivals automatically from a Wise Old Man group",
		position = 0
	)
	String groupSection = "group";

	@ConfigItem(
		keyName = "useWomGroup",
		name = "Use Wise Old Man group",
		description = "Populate the rival list from a Wise Old Man group instead of entering names manually",
		section = groupSection,
		position = 0,
		warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers"
	)
	default boolean useWomGroup()
	{
		return false;
	}

	@ConfigItem(
		keyName = "womGroupId",
		name = "WOM group ID",
		description = "The numeric ID from your Wise Old Man group's URL (wiseoldman.net/groups/<id>). Only used when the toggle above is enabled.",
		section = groupSection,
		position = 1
	)
	default int womGroupId()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "womMaxMembers",
		name = "Max members",
		description = "How many of the most recently active group members to track. Only used when the toggle above is enabled.",
		section = groupSection,
