package com.samwise0101.rivalry;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridLayout;
import java.awt.Image;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.client.hiscore.HiscoreSkillType;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.materialtabs.MaterialTab;
import net.runelite.client.ui.components.materialtabs.MaterialTabGroup;

public class RivalryPanel extends PluginPanel
{
	private static final Color CROWN_COLOR = new Color(255, 215, 0);
	private static final Color HEADER_COLOR = ColorScheme.BRAND_ORANGE;
	private static final Color AHEAD_COLOR = ColorScheme.PROGRESS_COMPLETE_COLOR;   // green
	private static final Color BEHIND_COLOR = ColorScheme.PROGRESS_ERROR_COLOR;     // red
	private static final int GRID_COLUMNS = 3;
	private static final int REACH_LIMIT = 10;

	private final IconLoader iconLoader;
	private final JPanel body = new JPanel();
	private final JLabel statusLabel = new JLabel("Not refreshed yet", SwingConstants.CENTER);
	private Runnable onRefresh;

	// Per-player expand state and last-open tab.
	private final Set<String> expanded = new HashSet<>();
	private final Map<String, String> selectedTab = new HashMap<>();

	// Top-level collapsible section state (retained across refreshes).
	private boolean rivalsExpanded = true;
	private boolean reachExpanded = true;
	private String reachSelectedTab = "Skills";
	private String reachSkillsMode = "By Level";

	// Last data received, so section toggles can re-render without a refresh.
	private List<PlayerStanding> lastStandings = Collections.emptyList();
	private String lastLocalPlayer = "";

	RivalryPanel(IconLoader iconLoader)
	{
		this.iconLoader = iconLoader;

		JLabel title = new JLabel("Rivalry", SwingConstants.CENTER);
		title.setFont(FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 16f));
		title.setForeground(HEADER_COLOR);
		add(title);

		JButton refreshBtn = new JButton("Refresh Now");
		refreshBtn.addActionListener(e -> { if (onRefresh != null) onRefresh.run(); });
		add(refreshBtn);

		statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		statusLabel.setFont(FontManager.getRunescapeSmallFont());
		add(statusLabel);

		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(body);
	}

	void setRefreshCallback(Runnable callback)
	{
		this.onRefresh = callback;
	}

	void setStatus(String message)
	{
		SwingUtilities.invokeLater(() -> statusLabel.setText(message));
	}

	/** Stores the latest data and rebuilds the panel. Callable from any thread. */
	void updateStandings(List<PlayerStanding> standings, String localPlayer, String lastUpdated)
	{
		SwingUtilities.invokeLater(() ->
		{
			lastStandings = standings;
			lastLocalPlayer = localPlayer;
			statusLabel.setText("Updated: " + lastUpdated);
			rebuild();
		});
	}

	// -------------------------------------------------------------------------
	// Layout
	// -------------------------------------------------------------------------

	private void rebuild()
	{
		body.removeAll();

		// --- Your crowns summary ---
		if (!lastStandings.isEmpty())
		{
			body.add(buildCrownSummary());
		}

		// --- Rivals section ---
		body.add(sectionHeader("Rivals", rivalsExpanded, () ->
		{
			rivalsExpanded = !rivalsExpanded;
			rebuild();
		}));

		if (rivalsExpanded)
		{
			if (lastStandings.isEmpty())
			{
				body.add(note("No rivals configured."));
			}
			else
			{
				lastStandings.stream()
					.sorted((a, b) -> b.getCrownCount() - a.getCrownCount())
					.forEach(s ->
					{
						boolean isLocal = s.getName().equalsIgnoreCase(lastLocalPlayer);
						body.add(buildPlayerRow(s, isLocal));
						if (expanded.contains(s.getName().toLowerCase()))
						{
							body.add(buildExpandSection(s));
						}
					});
			}
		}

		// --- Within Reach section ---
		body.add(sectionHeader("Within Reach", reachExpanded, () ->
		{
			reachExpanded = !reachExpanded;
			rebuild();
		}));

		if (reachExpanded)
		{
			body.add(buildReachContent());
		}

		body.add(Box.createVerticalGlue());
		body.revalidate();
		body.repaint();
	}

	private JComponent buildCrownSummary()
	{
		int total = lastStandings.stream().mapToInt(PlayerStanding::getCrownCount).sum();
		int mine = lastStandings.stream()
			.filter(s -> s.getName().equalsIgnoreCase(lastLocalPlayer))
			.mapToInt(PlayerStanding::getCrownCount)
			.findFirst()
			.orElse(0);

		JLabel summary = new JLabel("Your Crowns: " + mine + "/" + total + " 👑", SwingConstants.CENTER);
		summary.setFont(FontManager.getRunescapeBoldFont());
		summary.setForeground(CROWN_COLOR);
		summary.setHorizontalAlignment(SwingConstants.CENTER);
		summary.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		summary.setBorder(BorderFactory.createEmptyBorder(2, 4, 8, 4));
		summary.setAlignmentX(LEFT_ALIGNMENT);
		return summary;
	}

	private JComponent sectionHeader(String title, boolean isExpanded, Runnable onToggle)
	{
		JPanel header = new JPanel(new BorderLayout());
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.MEDIUM_GRAY_COLOR),
			BorderFactory.createEmptyBorder(5, 4, 5, 4)
		));
		header.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		header.setAlignmentX(LEFT_ALIGNMENT);
		header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

		JLabel label = new JLabel((isExpanded ? "▼ " : "▶ ") + title);
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(HEADER_COLOR);
		header.add(label, BorderLayout.WEST);

		header.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				onToggle.run();
			}
		});
		return header;
	}

	private JComponent note(String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setBorder(BorderFactory.createEmptyBorder(6, 4, 6, 4));
		label.setAlignmentX(LEFT_ALIGNMENT);
		return label;
	}

	// -------------------------------------------------------------------------
	// Rivals section
	// -------------------------------------------------------------------------

	private JComponent buildPlayerRow(PlayerStanding standing, boolean isLocal)
	{
		final String name = standing.getName();
		boolean isExpanded = expanded.contains(name.toLowerCase());

		JPanel row = new JPanel(new BorderLayout());
		row.setBackground(isLocal ? ColorScheme.DARKER_GRAY_COLOR : ColorScheme.DARK_GRAY_COLOR);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
			BorderFactory.createEmptyBorder(4, 6, 4, 6)
		));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		row.setAlignmentX(LEFT_ALIGNMENT);
		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

		String arrow = isExpanded ? "▼ " : "▶ ";
		JLabel nameLabel = new JLabel(arrow + (isLocal ? name + " (you)" : name));
		nameLabel.setForeground(isLocal ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
		nameLabel.setFont(FontManager.getRunescapeSmallFont());

		int crowns = standing.getCrownCount();
		JLabel crownLabel = new JLabel(crowns + " 👑");
		crownLabel.setForeground(crowns > 0 ? CROWN_COLOR : ColorScheme.MEDIUM_GRAY_COLOR);
		crownLabel.setFont(FontManager.getRunescapeSmallFont());
		crownLabel.setHorizontalAlignment(SwingConstants.RIGHT);

		row.add(nameLabel, BorderLayout.WEST);
		row.add(crownLabel, BorderLayout.EAST);

		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				String key = name.toLowerCase();
				if (!expanded.remove(key))
				{
					expanded.add(key);
				}
				rebuild();
			}
		});

		return row;
	}

	private JComponent buildExpandSection(PlayerStanding standing)
	{
		final String key = standing.getName().toLowerCase();

		JPanel wrapper = new JPanel(new BorderLayout());
		wrapper.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		wrapper.setBorder(BorderFactory.createEmptyBorder(2, 4, 6, 4));
		wrapper.setAlignmentX(LEFT_ALIGNMENT);

		JPanel display = new JPanel(new BorderLayout());
		display.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		MaterialTabGroup tabGroup = new MaterialTabGroup(display);
		tabGroup.setBorder(BorderFactory.createEmptyBorder(2, 0, 4, 0));

		MaterialTab skillsTab = new MaterialTab("Skills", tabGroup, buildGrid(standing, HiscoreSkillType.SKILL));
		MaterialTab bossesTab = new MaterialTab("Bosses", tabGroup, buildGrid(standing, HiscoreSkillType.BOSS));
		MaterialTab otherTab = new MaterialTab("Other", tabGroup, buildGrid(standing, HiscoreSkillType.ACTIVITY));

		skillsTab.setOnSelectEvent(() -> { selectedTab.put(key, "Skills"); return true; });
		bossesTab.setOnSelectEvent(() -> { selectedTab.put(key, "Bosses"); return true; });
		otherTab.setOnSelectEvent(() -> { selectedTab.put(key, "Other"); return true; });

		tabGroup.addTab(skillsTab);
		tabGroup.addTab(bossesTab);
		tabGroup.addTab(otherTab);
		selectTab(tabGroup, selectedTab.getOrDefault(key, "Skills"), skillsTab, bossesTab, otherTab);

		wrapper.add(tabGroup, BorderLayout.NORTH);
		wrapper.add(display, BorderLayout.CENTER);
		return wrapper;
	}

	private JComponent buildGrid(PlayerStanding standing, HiscoreSkillType type)
	{
		List<CategoryStat> all = standing.getStats().stream()
			.filter(c -> c.getType() == type)
			.collect(Collectors.toList());

		CategoryStat aggregate = all.stream().filter(CategoryStat::isAggregate).findFirst().orElse(null);
		List<CategoryStat> regular = all.stream()
			.filter(c -> !c.isAggregate())
			.sorted(Comparator.comparingInt(CategoryStat::getOrder))
			.collect(Collectors.toList());

		if (aggregate == null && regular.isEmpty())
		{
			return emptyTabPanel("Nothing ranked");
		}

		JPanel container = new JPanel();
		container.setLayout(new BoxLayout(container, BoxLayout.Y_AXIS));
		container.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		if (!regular.isEmpty())
		{
			JPanel grid = new JPanel(new GridLayout(0, GRID_COLUMNS, 4, 2));
			grid.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			grid.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));
			// Centre the grid block so left/right margins are even.
			grid.setAlignmentX(CENTER_ALIGNMENT);
			for (CategoryStat stat : regular)
			{
				grid.add(buildCell(stat));
			}
			container.add(grid);
		}

		// Aggregate (e.g. Total Level) gets its own centered full-width row below the grid.
		if (aggregate != null)
		{
			container.add(buildTotalRow(aggregate));
		}

		return container;
	}

	private JComponent buildTotalRow(CategoryStat aggregate)
	{
		JLabel row = new JLabel(aggregate.getName() + ": " + formatValue(aggregate), SwingConstants.CENTER);
		row.setFont(FontManager.getRunescapeSmallFont());
		row.setForeground(colorFor(aggregate));
		row.setHorizontalAlignment(SwingConstants.CENTER);
		row.setIconTextGap(4);
		row.setBorder(BorderFactory.createEmptyBorder(6, 6, 4, 6));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 22));
		row.setAlignmentX(CENTER_ALIGNMENT);
		iconLoader.apply(row, aggregate);
		return row;
	}

	// -------------------------------------------------------------------------
	// Within Reach section
	// -------------------------------------------------------------------------

	private JComponent buildReachContent()
	{
		PlayerStanding me = lastStandings.stream()
			.filter(s -> s.getName().equalsIgnoreCase(lastLocalPlayer))
			.findFirst()
			.orElse(null);

		if (me == null)
		{
			return note("Log in to see crowns within your reach.");
		}

		JPanel wrapper = new JPanel(new BorderLayout());
		wrapper.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		wrapper.setBorder(BorderFactory.createEmptyBorder(2, 4, 6, 4));
		wrapper.setAlignmentX(LEFT_ALIGNMENT);

		JPanel display = new JPanel(new BorderLayout());
		display.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		MaterialTabGroup tabGroup = new MaterialTabGroup(display);
		tabGroup.setBorder(BorderFactory.createEmptyBorder(2, 0, 4, 0));

		MaterialTab skillsTab = new MaterialTab("Skills", tabGroup, buildReachList(me, HiscoreSkillType.SKILL));
		MaterialTab bossesTab = new MaterialTab("Bosses", tabGroup, buildReachList(me, HiscoreSkillType.BOSS));
		MaterialTab otherTab = new MaterialTab("Other", tabGroup, buildReachList(me, HiscoreSkillType.ACTIVITY));

		skillsTab.setOnSelectEvent(() -> { reachSelectedTab = "Skills"; return true; });
		bossesTab.setOnSelectEvent(() -> { reachSelectedTab = "Bosses"; return true; });
		otherTab.setOnSelectEvent(() -> { reachSelectedTab = "Other"; return true; });

		tabGroup.addTab(skillsTab);
		tabGroup.addTab(bossesTab);
		tabGroup.addTab(otherTab);
		selectTab(tabGroup, reachSelectedTab, skillsTab, bossesTab, otherTab);

		wrapper.add(tabGroup, BorderLayout.NORTH);
		wrapper.add(display, BorderLayout.CENTER);
		return wrapper;
	}

	/** The closest crowns of a given type the local player doesn't hold. Skills get By Level / By XP sub-tabs. */
	private JComponent buildReachList(PlayerStanding me, HiscoreSkillType type)
	{
		if (type != HiscoreSkillType.SKILL)
		{
			return buildReachRows(me, type, false);
		}

		JPanel display = new JPanel(new BorderLayout());
		display.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		MaterialTabGroup group = new MaterialTabGroup(display);
		group.setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));

		MaterialTab byLevel = new MaterialTab("By Level", group, buildReachRows(me, type, false));
		MaterialTab byXp = new MaterialTab("By XP", group, buildReachRows(me, type, true));
		byLevel.setOnSelectEvent(() -> { reachSkillsMode = "By Level"; return true; });
		byXp.setOnSelectEvent(() -> { reachSkillsMode = "By XP"; return true; });
		group.addTab(byLevel);
		group.addTab(byXp);
		group.select("By XP".equals(reachSkillsMode) ? byXp : byLevel);

		JPanel wrapper = new JPanel(new BorderLayout());
		wrapper.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		wrapper.add(group, BorderLayout.NORTH);
		wrapper.add(display, BorderLayout.CENTER);
		return wrapper;
	}

	private JComponent buildReachRows(PlayerStanding me, HiscoreSkillType type, boolean xpMode)
	{
		List<CategoryStat> reachable;
		if (xpMode)
		{
			reachable = me.getStats().stream()
				.filter(s -> s.getType() == type && !s.isHoldsCrown() && s.getCrownDiff() != null && s.getCrownDiff() < 0)
				.sorted(Comparator.comparingLong(s -> -s.getCrownDiff())) // smallest XP deficit first
				.limit(REACH_LIMIT)
				.collect(Collectors.toList());
		}
		else
		{
			reachable = me.getStats().stream()
				.filter(s -> s.getType() == type && !s.isHoldsCrown() && s.getDiff() != null && s.getDiff() < 0)
				.sorted(Comparator.comparingInt(s -> -s.getDiff())) // smallest deficit first
				.limit(REACH_LIMIT)
				.collect(Collectors.toList());
		}

		if (reachable.isEmpty())
		{
			return emptyTabPanel("Nothing within reach");
		}

		JPanel list = new JPanel();
		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		list.setBorder(BorderFactory.createEmptyBorder(4, 2, 4, 2));
		for (CategoryStat stat : reachable)
		{
			list.add(buildReachRow(stat, xpMode));
		}
		return list;
	}

	private JComponent buildReachRow(CategoryStat stat, boolean xpMode)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.DARK_GRAY_COLOR),
			BorderFactory.createEmptyBorder(3, 4, 3, 4)
		));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		row.setAlignmentX(LEFT_ALIGNMENT);

		JLabel icon = new JLabel();
		iconLoader.apply(icon, stat);

		JLabel name = new JLabel(stat.getName());
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		String text = xpMode
			? String.format("%,d XP to go", -stat.getCrownDiff())
			: (-stat.getDiff()) + " to go";
		JLabel gapLabel = new JLabel(text);
		gapLabel.setFont(FontManager.getRunescapeSmallFont());
		gapLabel.setForeground(BEHIND_COLOR);
		gapLabel.setHorizontalAlignment(SwingConstants.RIGHT);

		row.add(icon, BorderLayout.WEST);
		row.add(name, BorderLayout.CENTER);
		row.add(gapLabel, BorderLayout.EAST);
		return row;
	}

	// -------------------------------------------------------------------------
	// Shared helpers
	// -------------------------------------------------------------------------

	private static void selectTab(MaterialTabGroup group, String which, MaterialTab skills, MaterialTab bosses, MaterialTab other)
	{
		// Use the GROUP's select() — it populates the display panel.
		switch (which)
		{
			case "Bosses":
				group.select(bosses);
				break;
			case "Other":
				group.select(other);
				break;
			default:
				group.select(skills);
		}
	}

	private JPanel emptyTabPanel(String text)
	{
		JPanel empty = new JPanel(new BorderLayout());
		empty.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		empty.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
		JLabel none = new JLabel(text, SwingConstants.CENTER);
		none.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		none.setFont(FontManager.getRunescapeSmallFont());
		empty.add(none, BorderLayout.CENTER);
		return empty;
	}

	private JLabel buildCell(CategoryStat stat)
	{
		JLabel cell = new JLabel(formatValue(stat));
		cell.setFont(FontManager.getRunescapeSmallFont());
		cell.setForeground(colorFor(stat));
		cell.setIconTextGap(2);
		// Centre the icon+value within each (full-width) grid cell so columns are even.
		cell.setHorizontalAlignment(SwingConstants.CENTER);
		cell.setToolTipText(stat.getName() + (stat.isHoldsCrown() ? "  (crown)" : ""));
		iconLoader.apply(cell, stat);
		return cell;
	}

	private static String formatValue(CategoryStat stat)
	{
		Integer diff = stat.getDiff();
		if (diff == null)
		{
			return "?";
		}
		// Holder shows their margin as +X (>= 0); others show their deficit (<= 0).
		if (stat.isHoldsCrown() || diff > 0)
		{
			return "+" + diff;
		}
		return String.valueOf(diff);
	}

	private static Color colorFor(CategoryStat stat)
	{
		Integer diff = stat.getDiff();
		if (diff == null)
		{
			return ColorScheme.LIGHT_GRAY_COLOR;
		}
		if (stat.isHoldsCrown())
		{
			return AHEAD_COLOR;
		}
		if (diff < 0)
		{
			return BEHIND_COLOR;
		}
		// diff == 0: behind on the tiebreak if a holder exists, otherwise a genuine tie.
		return stat.isHasHolder() ? BEHIND_COLOR : ColorScheme.LIGHT_GRAY_COLOR;
	}
}

package com.samwise0101.rivalry;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.TrayIcon;
import java.awt.image.BufferedImage;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CompletionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.FlashNotification;
import net.runelite.client.config.Notification;
import net.runelite.client.config.NotificationSound;
import net.runelite.client.config.RequestFocusType;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.Notifier;

@Slf4j
@PluginDescriptor(
	name = "Rivalry",
	description = "Track yourself and rivals across the OSRS hiscores and compete for crowns.",
	tags = {"hiscore", "rivalry", "crown", "rivals", "competition", "skilling", "pvm"}
)
public class RivalryPlugin extends Plugin
{
	private static final DateTimeFormatter TIME_FMT =
		DateTimeFormatter.ofPattern("HH:mm:ss").withZone(ZoneId.systemDefault());

	private static final long LOGIN_REFRESH_DELAY_SECONDS = 10;
	private static final long STARTUP_REFRESH_DELAY_SECONDS = 3;
	private static final String SUCCESS_SOUND = "/success.wav";
	private static final String FAILURE_SOUND = "/failure.wav";

	private static final String KEY_POLL_INTERVAL = "pollIntervalMinutes";
	// Config keys that change only how data is shown — recompute from cache, no re-fetch.
	private static final Set<String> DISPLAY_KEYS =
		Set.of("trackSkills", "trackBosses", "trackClues", "gapToNextPlayer");
	// Config keys that only affect notification delivery — no recompute needed.
	private static final Set<String> NOTIFICATION_KEYS =
		Set.of(
			RivalryConfig.CROWN_NOTIFICATIONS_ENABLED_KEY,
			RivalryConfig.CROWN_GAME_MESSAGE_KEY,
			RivalryConfig.CROWN_NOTIFICATION_SOUND_KEY,
			RivalryConfig.CROWN_NOTIFICATION_VOLUME_KEY,
			RivalryConfig.OLD_NOTIFY_GAME_CHAT_KEY,
			RivalryConfig.OLD_NOTIFY_DESKTOP_KEY);

	@Inject
	private Client client;

	@Inject
	private RivalryConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Notifier notifier;

	@Inject
	private AudioPlayer audioPlayer;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private IconLoader iconLoader;

	@Inject
	private RosterResolver rosterResolver;

	@Inject
	private HiscoreService hiscoreService;

	@Inject
	private CrownCalculator crownCalculator;

	@Inject
	private CrownStore crownStore;

	private RivalryPanel panel;
	private NavigationButton navButton;
	private ScheduledFuture<?> pollTask;

	// Cached on the client thread (GameTick) so executor threads can read it safely.
	private volatile String localPlayerName;

	// Inputs from the last successful compute, so display-only changes can recompute
	// without re-fetching. The stats map is treated as immutable once stored.
	private volatile List<String> lastRoster;
	private volatile Map<String, PlayerStats> lastStats;
	private volatile String lastComputeLocalName;

	private boolean seeded = false;

	@Override
	protected void startUp()
	{
		migrateNotificationConfig();

		panel = new RivalryPanel(iconLoader);
		panel.setRefreshCallback(this::triggerRefresh);

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/rivalry_icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Rivalry")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		crownStore.load();
		schedulePoll();

		// If the plugin is enabled while already logged in, no LOGGED_IN event fires,
		// so kick off an initial refresh ourselves.
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			executor.schedule(this::refresh, STARTUP_REFRESH_DELAY_SECONDS, TimeUnit.SECONDS);
		}

		log.info("Rivalry started");
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		if (pollTask != null)
		{
			pollTask.cancel(false);
			pollTask = null;
		}
		seeded = false;
		log.info("Rivalry stopped");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGED_IN)
		{
			// Trigger a refresh shortly after login so data is fresh
			executor.schedule(this::refresh, LOGIN_REFRESH_DELAY_SECONDS, TimeUnit.SECONDS);
		}
		else if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			localPlayerName = null;
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		// Runs on the client thread — safe to read the local player here.
		Player local = client.getLocalPlayer();
		String name = local != null ? local.getName() : null;
		if (name != null && !name.equals(localPlayerName))
		{
			localPlayerName = name;
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!RivalryConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		String key = event.getKey();
		if (KEY_POLL_INTERVAL.equals(key))
		{
			schedulePoll();
		}
		else if (NOTIFICATION_KEYS.contains(key))
		{
			// Purely how we notify — nothing to recompute.
		}
		else if (DISPLAY_KEYS.contains(key))
		{
			// Category/display options don't change the fetched data, so recompute
			// from the cached stats instead of hitting the hiscores again.
			recomputeFromCache();
		}
		else
		{
			// Roster/group settings changed — need a fresh fetch.
			triggerRefresh();
		}
	}

	@Provides
	RivalryConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RivalryConfig.class);
	}

	private void migrateNotificationConfig()
	{
		Notification oldNotification = getOldCrownNotification();
		String oldGameChat = configManager.getConfiguration(RivalryConfig.GROUP, RivalryConfig.OLD_NOTIFY_GAME_CHAT_KEY);

		if (configManager.getConfiguration(RivalryConfig.GROUP, RivalryConfig.CROWN_NOTIFICATIONS_ENABLED_KEY) == null)
		{
			boolean enabled = oldNotification == null || oldNotification.isEnabled();
			configManager.setConfiguration(RivalryConfig.GROUP, RivalryConfig.CROWN_NOTIFICATIONS_ENABLED_KEY, enabled);
		}

		if (configManager.getConfiguration(RivalryConfig.GROUP, RivalryConfig.CROWN_GAME_MESSAGE_KEY) == null)
		{
			boolean gameMessage = oldNotification != null
				? oldNotification.isGameMessage()
				: oldGameChat == null || Boolean.parseBoolean(oldGameChat);
			configManager.setConfiguration(RivalryConfig.GROUP, RivalryConfig.CROWN_GAME_MESSAGE_KEY, gameMessage);
		}

		if (oldNotification != null)
		{
			if (configManager.getConfiguration(RivalryConfig.GROUP, RivalryConfig.CROWN_NOTIFICATION_SOUND_KEY) == null)
			{
				configManager.setConfiguration(RivalryConfig.GROUP, RivalryConfig.CROWN_NOTIFICATION_SOUND_KEY,
					oldNotification.isEnabled() && oldNotification.getSound() != NotificationSound.OFF);
			}

			if (configManager.getConfiguration(RivalryConfig.GROUP, RivalryConfig.CROWN_NOTIFICATION_VOLUME_KEY) == null)
			{
				configManager.setConfiguration(RivalryConfig.GROUP, RivalryConfig.CROWN_NOTIFICATION_VOLUME_KEY,
					oldNotification.getVolume());
			}
		}

		configManager.unsetConfiguration(RivalryConfig.GROUP, RivalryConfig.CROWN_NOTIFICATION_KEY);
		configManager.unsetConfiguration(RivalryConfig.GROUP, RivalryConfig.OLD_NOTIFY_GAME_CHAT_KEY);
		configManager.unsetConfiguration(RivalryConfig.GROUP, RivalryConfig.OLD_NOTIFY_DESKTOP_KEY);
		log.debug("Migrated Rivalry notification config");
	}

	private Notification getOldCrownNotification()
	{
		try
		{
			return configManager.getConfiguration(RivalryConfig.GROUP, RivalryConfig.CROWN_NOTIFICATION_KEY,
				Notification.class);
		}
		catch (Exception e)
		{
			log.debug("Could not read old Rivalry crown notification config", e);
			return null;
		}
	}

	// -------------------------------------------------------------------------
	// Scheduling
	// -------------------------------------------------------------------------

	private void schedulePoll()
	{
		if (pollTask != null)
		{
			pollTask.cancel(false);
		}
		long intervalMinutes = config.pollIntervalMinutes();
		pollTask = executor.scheduleAtFixedRate(this::refresh, intervalMinutes, intervalMinutes, TimeUnit.MINUTES);
	}

	private void triggerRefresh()
	{
		executor.execute(this::refresh);
	}

	/** Recompute standings from the last fetched stats (for display-only changes), or refresh if none. */
	private void recomputeFromCache()
	{
		List<String> roster = lastRoster;
		Map<String, PlayerStats> stats = lastStats;
		if (roster == null || stats == null)
		{
			triggerRefresh();
			return;
		}
		executor.execute(() -> computeAndUpdate(lastComputeLocalName, roster, stats));
	}

	// -------------------------------------------------------------------------
	// Core refresh logic
	// -------------------------------------------------------------------------

	private void refresh()
	{
		final String localName = localPlayerName;

		rosterResolver.resolve(localName).whenComplete((roster, rosterErr) ->
		{
			if (rosterErr != null)
			{
				panel.setStatus(userMessage(rosterErr));
				return;
			}
			if (roster.isEmpty())
			{
				panel.setStatus(config.useWomGroup() ? "WOM group has no members." : "Configure rivals in settings.");
				return;
			}

			panel.setStatus("Refreshing...");
			hiscoreService.fetch(roster).whenComplete((stats, fetchErr) ->
			{
				if (fetchErr != null)
				{
					log.warn("Hiscore fetch failed", fetchErr);
					panel.setStatus("Refresh failed — see logs");
					return;
				}
				computeAndUpdate(localName, roster, stats);
			});
		});
	}

	private static String userMessage(Throwable t)
	{
		Throwable cause = t instanceof CompletionException && t.getCause() != null ? t.getCause() : t;
		String message = cause.getMessage();
		return message != null ? message : "Could not resolve rivals.";
	}

	private void computeAndUpdate(String localName, List<String> roster, Map<String, PlayerStats> stats)
	{
		// Remember the inputs so display-only config changes can recompute cheaply.
		lastRoster = roster;
		lastStats = stats;
		lastComputeLocalName = localName;

		try
		{
			CrownOptions options = new CrownOptions(
				config.trackSkills(), config.trackBosses(), config.trackClues(), config.gapToNextPlayer());
			CrownResult result = crownCalculator.calculate(roster, stats, options);

			applyHolderChanges(localName, result.getHolders());

			String timestamp = TIME_FMT.format(Instant.now());
			panel.updateStandings(result.getStandings(), localName != null ? localName : "", timestamp);
		}
		catch (Exception e)
		{
			// Async callbacks swallow exceptions; log and clear the status so the
			// panel never gets stuck on "Refreshing...".
			log.warn("Failed to compute crown standings", e);
			panel.setStatus("Refresh failed — see logs");
		}
	}

	/**
	 * Compares the freshly-computed crown holders against the stored ones, firing
	 * gain/loss notifications for the local player and persisting the new holders.
	 */
	private void applyHolderChanges(String localName, Map<String, String> newHolders)
	{
		for (Map.Entry<String, String> entry : newHolders.entrySet())
		{
			String id = entry.getKey();
			String newHolder = entry.getValue();
			String prevHolder = crownStore.getHolder(id);

			if (seeded && !sameHolder(newHolder, prevHolder))
			{
				boolean localHeld = localName != null && localName.equalsIgnoreCase(prevHolder);
				boolean localGained = localName != null && localName.equalsIgnoreCase(newHolder);
				String name = CrownCalculator.categoryDisplayName(id);

				if (localGained)
				{
					notify("You claimed the " + name + " crown!", SUCCESS_SOUND);
				}
				else if (localHeld)
				{
					notify(newHolder != null
						? "You lost the " + name + " crown to " + newHolder + "!"
						: "You lost the " + name + " crown!", FAILURE_SOUND);
				}
			}

			crownStore.setHolder(id, newHolder);
		}

		seeded = true;
	}

	private static boolean sameHolder(String a, String b)
	{
		return (a == null ? "" : a).equalsIgnoreCase(b == null ? "" : b);
	}

	private void notify(String message, String soundResource)
	{
		if (!config.crownNotificationsEnabled())
		{
			return;
		}

		notifier.notify(crownNotification(), message);
		playNotificationSound(soundResource);
	}

	private Notification crownNotification()
	{
		return new Notification(
			true,
			true,
			true,
			false,
			TrayIcon.MessageType.NONE,
			RequestFocusType.OFF,
			NotificationSound.OFF,
			null,
			100,
			0,
			config.crownGameMessage(),
			FlashNotification.DISABLED,
			new Color(255, 0, 0, 70),
			true);
	}

	private void playNotificationSound(String resourcePath)
	{
		if (!config.crownNotificationsEnabled() || !config.crownNotificationSound())
		{
			return;
		}

		int volume = Math.max(0, Math.min(100, config.crownNotificationVolume()));
		if (volume == 0)
		{
			return;
		}

		// Convert a 0-100 volume to a MASTER_GAIN value in decibels (0 dB at full volume).
		float gain = (float) (20.0 * Math.log10(volume / 100.0));
		executor.execute(() ->
		{
			try
			{
				audioPlayer.play(getClass(), resourcePath, gain);
			}
			catch (Exception e)
			{
				log.debug("Unable to play notification sound {}", resourcePath, e);
			}
		});
	}
}

package com.samwise0101.rivalry;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Produces the player roster to track: either the manual rival list or the
 * members of a Wise Old Man group. The local player is always placed first.
 */
@Singleton
class RosterResolver
{
	private final RivalryConfig config;
	private final WomClient womClient;

	// Last successful WOM roster, used as a fallback when a fetch fails.
	private volatile List<String> lastWomMembers;

	@Inject
	RosterResolver(RivalryConfig config, WomClient womClient)
	{
		this.config = config;
		this.womClient = womClient;
	}

	/**
	 * Resolves the roster. Completes exceptionally with a {@link RosterException}
	 * whose message is suitable for display when the roster can't be determined.
	 */
	CompletableFuture<List<String>> resolve(String localName)
	{
		if (!config.useWomGroup())
		{
			return CompletableFuture.completedFuture(buildManualRoster(localName));
		}

		CompletableFuture<List<String>> future = new CompletableFuture<>();
		int groupId = config.womGroupId();
		if (groupId <= 0)
		{
			future.completeExceptionally(new RosterException("Set a WOM group ID in settings."));
			return future;
		}

		womClient.fetchGroupMembers(groupId, config.womMaxMembers(),
			members ->
			{
				lastWomMembers = members;
				future.complete(withLocalPlayer(localName, members));
			},
			error ->
			{
				if (lastWomMembers != null)
				{
					future.complete(withLocalPlayer(localName, lastWomMembers));
				}
				else
				{
					future.completeExceptionally(new RosterException("WOM group fetch failed — check the group ID."));
				}
			});
		return future;
	}

	private List<String> buildManualRoster(String localName)
	{
		List<String> players = new ArrayList<>();
		addIfNotBlank(players, localName);
		addIfNotBlank(players, config.rival1());
		addIfNotBlank(players, config.rival2());
		addIfNotBlank(players, config.rival3());
		addIfNotBlank(players, config.rival4());
		addIfNotBlank(players, config.rival5());
		return players;
	}

	private static List<String> withLocalPlayer(String localName, List<String> members)
	{
		List<String> players = new ArrayList<>();
		addIfNotBlank(players, localName);
		for (String m : members)
		{
			if (m != null && players.stream().noneMatch(p -> p.equalsIgnoreCase(m)))
			{
				players.add(m);
			}
		}
		return players;
	}

	private static void addIfNotBlank(List<String> list, String value)
	{
		if (value != null && !value.isBlank()
			&& list.stream().noneMatch(p -> p.equalsIgnoreCase(value.trim())))
		{
			list.add(value.trim());
		}
	}

	/** Thrown when the roster cannot be resolved; the message is user-facing. */
	static class RosterException extends RuntimeException
	{
		RosterException(String message)
		{
			super(message);
		}
	}
}

package com.samwise0101.rivalry;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.function.Consumer;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Reads group membership from the public Wise Old Man API. Used only to populate
 * the rival roster; all stat tracking still comes from the official hiscores.
 */
@Slf4j
public class WomClient
{
	private static final HttpUrl API_BASE = HttpUrl.get("https://api.wiseoldman.net/v2");
	private static final String USER_AGENT = "Rivalry RuneLite Plugin - https://github.com/samwise0101/rivalry";

	private final OkHttpClient okHttpClient;
	private final Gson gson;

	@Inject
	WomClient(OkHttpClient okHttpClient, Gson gson)
	{
		this.okHttpClient = okHttpClient;
		this.gson = gson;
	}

	/**
	 * Asynchronously fetches the members of a WOM group, sorted by most recent
	 * activity and limited to {@code maxMembers}. Callbacks run on an OkHttp thread.
	 */
	void fetchGroupMembers(int groupId, int maxMembers, Consumer<List<String>> onSuccess, Consumer<Exception> onError)
	{
		HttpUrl url = API_BASE.newBuilder()
			.addPathSegment("groups")
			.addPathSegment(Integer.toString(groupId))
			.build();

		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();

		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				onError.accept(e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (!r.isSuccessful() || r.body() == null)
					{
						onError.accept(new IOException("WOM returned HTTP " + r.code()));
						return;
					}

					WomGroup group = gson.fromJson(r.body().charStream(), WomGroup.class);
					if (group == null || group.memberships == null)
					{
						onError.accept(new IOException("Unexpected WOM response"));
						return;
					}

					onSuccess.accept(selectMembers(group, maxMembers));
				}
				catch (Exception e)
				{
					onError.accept(e);
				}
			}
		});
	}

	/**
	 * Picks the members to track: most recently active first (lastChangedAt
	 * descending, nulls last), limited to {@code maxMembers}, using displayName
	 * with a username fallback. Pure — unit tested directly.
	 */
	static List<String> selectMembers(WomGroup group, int maxMembers)
	{
		List<String> members = new ArrayList<>();
		if (group == null || group.memberships == null)
		{
			return members;
		}
		group.memberships.stream()
			.filter(m -> m != null && m.player != null && m.player.name() != null)
			// ISO-8601 timestamps sort chronologically as strings.
			.sorted(Comparator.comparing(
				(WomMembership m) -> m.player.lastChangedAt == null ? "" : m.player.lastChangedAt)
				.reversed())
			.limit(Math.max(1, maxMembers))
			.forEach(m -> members.add(m.player.name()));
		return members;
	}

	// --- Minimal Gson models (unknown fields are ignored) ---

	static class WomGroup
	{
		List<WomMembership> memberships;
	}

	static class WomMembership
	{
		WomPlayer player;
	}

	static class WomPlayer
	{
		String username;
		String displayName;
		String lastChangedAt;

		String name()
		{
			return displayName != null ? displayName : username;
		}
	}
}

package com.samwise0101.rivalry;

import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.client.hiscore.HiscoreSkill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class CrownCalculatorTest
{
	private final CrownCalculator calculator = new CrownCalculator();

	private static final CrownOptions SKILLS_ONLY = new CrownOptions(true, false, false, false);
	private static final CrownOptions SKILLS_GAP_TO_NEXT = new CrownOptions(true, false, false, true);

	@Test
	public void strictLeaderHoldsCrown()
	{
		TestStats alice = new TestStats().skill(HiscoreSkill.ATTACK, 1000, 10);
		TestStats bob = new TestStats().skill(HiscoreSkill.ATTACK, 500, 8);

		CrownResult r = calc(SKILLS_ONLY, roster("Alice", "Bob"), alice, bob);

		assertEquals("Alice", r.getHolders().get("ATTACK"));
		assertEquals(1, crownCount(r, "Alice"));
		assertEquals(0, crownCount(r, "Bob"));

		CategoryStat aliceAtk = stat(r, "Alice", "Attack");
		assertTrue(aliceAtk.isHoldsCrown());
		assertEquals(Integer.valueOf(2), aliceAtk.getDiff());        // 10 - runner-up 8
		assertEquals(Long.valueOf(500), aliceAtk.getCrownDiff());     // 1000 - 500

		CategoryStat bobAtk = stat(r, "Bob", "Attack");
		assertFalse(bobAtk.isHoldsCrown());
		assertTrue(bobAtk.isHasHolder());
		assertEquals(Integer.valueOf(-2), bobAtk.getDiff());          // 8 - top 10
	}

	@Test
	public void tieForLeadIsContested()
	{
		TestStats alice = new TestStats().skill(HiscoreSkill.ATTACK, 1000, 10);
		TestStats bob = new TestStats().skill(HiscoreSkill.ATTACK, 1000, 10);

		CrownResult r = calc(SKILLS_ONLY, roster("Alice", "Bob"), alice, bob);

		assertNull("contested crown has no holder", r.getHolders().get("ATTACK"));
		assertEquals(0, crownCount(r, "Alice"));
		assertEquals(0, crownCount(r, "Bob"));

		CategoryStat aliceAtk = stat(r, "Alice", "Attack");
		assertFalse(aliceAtk.isHoldsCrown());
		assertFalse(aliceAtk.isHasHolder());
		assertEquals(Integer.valueOf(0), aliceAtk.getDiff());
	}

	@Test
	public void sameLevelButLessXpIsBehind()
	{
		TestStats alice = new TestStats().skill(HiscoreSkill.ATTACK, 14_000_000, 99);
		TestStats bob = new TestStats().skill(HiscoreSkill.ATTACK, 13_000_000, 99);

		CrownResult r = calc(SKILLS_ONLY, roster("Alice", "Bob"), alice, bob);

		assertEquals("Alice", r.getHolders().get("ATTACK"));
		CategoryStat bobAtk = stat(r, "Bob", "Attack");
		assertFalse(bobAtk.isHoldsCrown());
		assertTrue(bobAtk.isHasHolder());          // drives the red-zero UI rule
		assertEquals(Integer.valueOf(0), bobAtk.getDiff());
		assertTrue(bobAtk.getCrownDiff() < 0);     // behind on XP
	}

	@Test
	public void gapToNextPlayerComparesToPlayerAbove()
	{
		TestStats alice = new TestStats().skill(HiscoreSkill.ATTACK, 300, 30);
		TestStats bob = new TestStats().skill(HiscoreSkill.ATTACK, 200, 20);
		TestStats carol = new TestStats().skill(HiscoreSkill.ATTACK, 100, 10);

		CrownResult dflt = calc(SKILLS_ONLY, roster("Alice", "Bob", "Carol"), alice, bob, carol);
		assertEquals(Integer.valueOf(-20), stat(dflt, "Carol", "Attack").getDiff()); // vs top (30)

		CrownResult gap = calc(SKILLS_GAP_TO_NEXT, roster("Alice", "Bob", "Carol"), alice, bob, carol);
		assertEquals(Integer.valueOf(-10), stat(gap, "Carol", "Attack").getDiff());  // vs Bob (20)
	}

	@Test
	public void unrankedSkillShownAsNullDiff()
	{
		TestStats alice = new TestStats().skill(HiscoreSkill.ATTACK, 500, 8);
		TestStats bob = new TestStats(); // unranked in everything

		CrownResult r = calc(SKILLS_ONLY, roster("Alice", "Bob"), alice, bob);

		CategoryStat bobAtk = stat(r, "Bob", "Attack");
		assertNotNull("skills are always listed", bobAtk);
		assertNull(bobAtk.getDiff());
	}

	@Test
	public void unrankedBossIsOmitted()
	{
		CrownOptions bossesOnly = new CrownOptions(false, true, false, false);
		TestStats alice = new TestStats().skill(HiscoreSkill.ZULRAH, 500, 500);
		TestStats bob = new TestStats(); // no Zulrah KC

		CrownResult r = calc(bossesOnly, roster("Alice", "Bob"), alice, bob);

		assertEquals("Alice", r.getHolders().get("ZULRAH"));
		assertNotNull(stat(r, "Alice", "Zulrah"));
		assertNull("unranked boss not listed for that player", stat(r, "Bob", "Zulrah"));
	}

	@Test
	public void aggregateTotalLevelAndBossKc()
	{
		CrownOptions skillsAndBosses = new CrownOptions(true, true, false, false);
		TestStats alice = new TestStats().totals(1_000_000, 500, 300);
		TestStats bob = new TestStats().totals(800_000, 450, 200);

		CrownResult r = calc(skillsAndBosses, roster("Alice", "Bob"), alice, bob);

		assertEquals("Alice", r.getHolders().get(CrownCalculator.TOTAL_LEVEL_ID));
		assertEquals("Alice", r.getHolders().get(CrownCalculator.TOTAL_BOSS_KC_ID));

		CategoryStat total = stat(r, "Alice", "Total Level");
		assertTrue(total.isAggregate());
		assertEquals(Integer.valueOf(50), total.getDiff());            // 500 - 450
		assertEquals(Long.valueOf(200_000), total.getCrownDiff());     // 1,000,000 - 800,000
	}

	// --- helpers ---

	private CrownResult calc(CrownOptions options, List<String> roster, TestStats... players)
	{
		Map<String, PlayerStats> stats = new HashMap<>();
		for (int i = 0; i < roster.size(); i++)
		{
			stats.put(roster.get(i).toLowerCase(), players[i]);
		}
		return calculator.calculate(roster, stats, options);
	}

	private static List<String> roster(String... names)
	{
		return Arrays.asList(names);
	}

	private static int crownCount(CrownResult r, String player)
	{
		return r.getStandings().stream()
			.filter(s -> s.getName().equals(player))
			.findFirst().orElseThrow(AssertionError::new)
			.getCrownCount();
	}

	private static CategoryStat stat(CrownResult r, String player, String categoryName)
	{
		return r.getStandings().stream()
			.filter(s -> s.getName().equals(player))
			.findFirst().orElseThrow(AssertionError::new)
			.getStats().stream()
			.filter(c -> c.getName().equals(categoryName))
			.findFirst().orElse(null);
	}

	/** A hand-built {@link PlayerStats} for tests. */
	private static final class TestStats implements PlayerStats
	{
		private final Map<HiscoreSkill, Long> crown = new HashMap<>();
		private final Map<HiscoreSkill, Integer> display = new HashMap<>();
		private long overallXp = -1;
		private int totalLevel = -1;
		private int totalBossKc = -1;

		TestStats skill(HiscoreSkill skill, long crownValue, int displayValue)
		{
			crown.put(skill, crownValue);
			display.put(skill, displayValue);
			return this;
		}

		TestStats totals(long overallXp, int totalLevel, int totalBossKc)
		{
			this.overallXp = overallXp;
			this.totalLevel = totalLevel;
			this.totalBossKc = totalBossKc;
			return this;
		}

		@Override
		public long crownValue(HiscoreSkill skill)
		{
			return crown.getOrDefault(skill, -1L);
		}

		@Override
		public int displayValue(HiscoreSkill skill)
		{
			return display.getOrDefault(skill, -1);
		}

		@Override
		public long overallXp()
		{
			return overallXp;
		}

		@Override
		public int totalLevel()
		{
			return totalLevel;
		}

		@Override
		public int totalBossKc()
		{
			return totalBossKc;
		}
	}
}

package com.samwise0101.rivalry;

import java.util.EnumMap;
import java.util.Map;
import net.runelite.client.hiscore.HiscoreResult;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.Skill;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class PlayerSnapshotTest
{
	private static PlayerSnapshot snapshot(Map<HiscoreSkill, Skill> skills)
	{
		return new PlayerSnapshot("Player", new HiscoreResult("Player", skills));
	}

	private static Skill skill(int rank, int level, long xp)
	{
		return new Skill(rank, level, xp);
	}

	@Test
	public void crownValueIsXpForSkillsAndScoreOtherwise()
	{
		Map<HiscoreSkill, Skill> skills = new EnumMap<>(HiscoreSkill.class);
		skills.put(HiscoreSkill.ATTACK, skill(1, 92, 6_500_000));
		skills.put(HiscoreSkill.ZULRAH, skill(1, 1234, -1)); // boss KC lives in level
		PlayerSnapshot snap = snapshot(skills);

		assertEquals(6_500_000L, snap.crownValue(HiscoreSkill.ATTACK)); // XP
		assertEquals(92, snap.displayValue(HiscoreSkill.ATTACK));        // level
		assertEquals(1234L, snap.crownValue(HiscoreSkill.ZULRAH));       // KC
		assertEquals(1234, snap.displayValue(HiscoreSkill.ZULRAH));      // KC
	}

	@Test
	public void unrankedReturnsMinusOne()
	{
		PlayerSnapshot snap = snapshot(new EnumMap<>(HiscoreSkill.class));
		assertEquals(-1L, snap.crownValue(HiscoreSkill.ATTACK));
		assertEquals(-1, snap.displayValue(HiscoreSkill.ATTACK));
	}

	@Test
	public void overallAndTotalLevel()
	{
		Map<HiscoreSkill, Skill> skills = new EnumMap<>(HiscoreSkill.class);
		skills.put(HiscoreSkill.OVERALL, skill(1, 1500, 200_000_000));
		PlayerSnapshot snap = snapshot(skills);

		assertEquals(200_000_000L, snap.overallXp());
		assertEquals(1500, snap.totalLevel());
	}

	@Test
	public void overallAbsentReturnsMinusOne()
	{
		PlayerSnapshot snap = snapshot(new EnumMap<>(HiscoreSkill.class));
		assertEquals(-1L, snap.overallXp());
		assertEquals(-1, snap.totalLevel());
	}

	@Test
	public void totalBossKcSumsRankedBosses()
	{
		Map<HiscoreSkill, Skill> skills = new EnumMap<>(HiscoreSkill.class);
		skills.put(HiscoreSkill.ZULRAH, skill(1, 500, -1));
		skills.put(HiscoreSkill.VORKATH, skill(1, 300, -1));
		skills.put(HiscoreSkill.ATTACK, skill(1, 99, 13_000_000)); // not a boss, ignored
		PlayerSnapshot snap = snapshot(skills);

		assertEquals(800, snap.totalBossKc());
	}

	@Test
	public void totalBossKcMinusOneWhenNoBosses()
	{
		Map<HiscoreSkill, Skill> skills = new EnumMap<>(HiscoreSkill.class);
		skills.put(HiscoreSkill.ATTACK, skill(1, 99, 13_000_000));
		assertEquals(-1, snapshot(skills).totalBossKc());
	}

	@Test
	public void nullResultIsAllMinusOne()
	{
		PlayerSnapshot snap = new PlayerSnapshot("Player", null);
		assertEquals(-1L, snap.crownValue(HiscoreSkill.ATTACK));
		assertEquals(-1, snap.displayValue(HiscoreSkill.ATTACK));
		assertEquals(-1L, snap.overallXp());
		assertEquals(-1, snap.totalLevel());
		assertEquals(-1, snap.totalBossKc());
	}
}

